"""Author development-only overlay definitions; never writes corpus or frozen holdout."""
import json,hashlib,copy
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
DEST=ROOT/'overlays'
def dump(p,x):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(x,indent=2,sort_keys=True)+'\n')
def case(cid):
 base=ROOT/'corpus/development'/cid
 return json.loads((base/'private/oracle.json').read_text()),json.loads((base/'manifest.json').read_text()),json.loads((base/'private/simulator.json').read_text())
def make(oid,cid,description,stages):
 o,m,s=case(cid);docs={d['documentId']:d for d in m['documents']};roles=o['roles'];out=[];inputs=[]
 for i,st in enumerate(stages):
  active=[roles[r] for r in st['active']];inactive=[roles[r] for r in st.get('inactive',[])];pending=[roles[r] for r in st.get('pending',[])];new=[roles[r] for r in st.get('new',[])]
  findings=copy.deepcopy(o['checkpoints'][st.get('gold',3)-1]['findings'])
  for f in findings:
   f['supportGroups']=[[r for r in g if r['documentId'] in active] for g in f['supportGroups']]
   f['supportGroups']=[g for g in f['supportGroups'] if g]
   if f['criterionId'] in st.get('states',{}):f['state']=st['states'][f['criterionId']]
   if f['state']=='met' and st.get('reuse',{}).get(f['criterionId']):
    f['supportGroups']=[[{'documentId':roles[r],'page':p}] for r,p in st['reuse'][f['criterionId']]]
  constraints={f['criterionId']:{'allowedStates':[f['state']],'supportGroups':f['supportGroups'] if f['state']=='met' else []} for f in findings}
  for f in findings:
   if f['state']=='met':continue
   critid=f['criterionId'];request=json.loads((ROOT/'corpus/development'/m['caseId']/'agent/request.json').read_text())
   constraints[critid]['gapExpectation']={'kind':'missing_evidence' if f['state']=='unmet' else 'unreadable' if oid=='DEV-UPLOAD-RACE' and st['id'] in ['unclear_copy','upload_in_flight'] else 'clarification','owner':st.get('owner') or 'borrower','subject':s['facts']['borrower'] if critid.startswith(('R4','R5')) else s['facts']['property'],'period':{'R4.july':'2026-07','R4.august':'2026-08','R4.september':'2026-09','R3.year':'2025-01-01/2025-12-31','R3.current':'2026-01-01/2026-09-30','R3.compare':'2026-01-01/2026-09-30'}.get(critid,None if critid.startswith('R5') else '2026-09-30'),'documentRole':request['policy']['criteria'][critid],'description':('Not yet supplied: ' if f['state']=='unmet' else 'Not yet established at this boundary: ')+request['policy']['criteria'][critid]+' '+st['trigger']}
  out.append({'boundaryId':st['id'],'trigger':st['trigger'],'expected':{'activeDocumentIds':active,'inactiveDocumentIds':inactive,'pendingUploadIds':pending,'evidenceRevision':str(st['revision']),'runState':st['runState'],'currentResultRevision':st.get('result'),'retainedObservationIds':st.get('observations',[]),'nextActionOwner':st.get('owner'),'criterionConstraints':constraints,'preserveCriteria':st.get('preserve',[]),'requiredReuseDocumentIds':[roles[r] for r in st.get('requiredReuse',[])],'requireNonzeroReuse':st.get('requireReuse',False),'budgetLimitMicros':st.get('budgetLimit',0),'spentMicros':st.get('spent',0),'reservedMicros':st.get('reserved',0)},'semanticRequirements':st['review'],'allowedQuestionTopics':st.get('topics',[]),'transcriptCategory':st['category'],'sourceOracleCheckpoint':st.get('gold',3)})
  saved=[]
  for d in active+inactive:
   item={k:docs[d][k] for k in ['documentId','sha256','filename','pageCount','seriesId','version']}
   item.update({'activity':'active' if d in active else 'superseded','arrival':'newly_saved' if d in new else 'previously_saved','linked':False})
   saved.append(item)
  inputs.append({'boundaryId':st['id'],'borrowerText':st.get('message'),'savedFiles':saved,'pendingUploads':[{'documentId':d,'filename':docs[d]['filename'],'status':'uploading'} for d in pending],'newlySavedDocumentIds':new,'evidenceRevision':str(st['revision']),'runtimeNotice':st.get('notice')})
 bindings={d:docs[d]['sha256'] for d in {x for stage in out for k in ['activeDocumentIds','inactiveDocumentIds','pendingUploadIds'] for x in stage['expected'][k]}}
 dump(DEST/oid/'oracle.json',{'version':'journey-overlays.1','status':'provisional','overlayId':oid,'baseCase':cid,'split':'development','description':description,'boundaries':out,'sourceHashes':bindings,'baseOracleSha256':hashlib.sha256((ROOT/f'corpus/development/{cid}/private/oracle.json').read_bytes()).hexdigest(),'orderingRule':'Boundaries describe evaluator-controlled input and lifecycle transitions, not prescribed agent actions or tool/page order. All extra responses must also be logged and reviewed.'})
 dump(DEST/oid/'scenario.json',{'version':'journey-overlays.1','baseCase':cid,'inputs':inputs,'borrowerPrivateFacts':s['facts'],'disclosureRules':s['disclosureRules']+['Do not request re-upload of qualifying previously saved evidence.','Boundary release follows external event/answer, not a fixed agent question.','Never reveal the oracle, expected state, future boundary or authorization test ledger.']})

allroles=['roll','leases','annual','current','bank7','bank8','bank9','formation','governing']
entitymissing={k:'unmet' for k in ['R5.formation','R5.governing','R5.consistency']}
# D02 changes availability only: old incomplete August is inactive; complete August already saved.
initialstates={'R2.leases':'unmet','R2.compare':'unknown','R3.current':'unmet','R3.compare':'unknown','R4.september':'unmet',**entitymissing}
history=[dict(id='existing_inventory',trigger='Conversation opens with existing saved evidence and a new roll.',active=['roll','annual','bank7','bank8'],inactive=['bank_partial'],new=['roll'],revision=4,runState='succeeded',result='4',states=initialstates,category='initial',message='Please use my saved annual report and July/August statements. The older partial August copy was superseded. I have no lease or entity amendments.',reuse={'R4.august':[('bank8',1),('bank8',2)]},requiredReuse=['annual','bank7','bank8'],review=['Distinguish previously saved active evidence from new roll and superseded partial August.','Reuse qualifying annual and bank evidence; do not request their re-upload.','Identify remaining lease/current-period/September/entity pieces.']),dict(id='incremental_arrival',trigger='Additional files saved, including a renamed July duplicate.',active=allroles[:-2]+['duplicate'],inactive=['bank_partial'],new=['leases','current','bank9','duplicate'],revision=5,runState='succeeded',result='5',states=entitymissing,category='correction',requiredReuse=['annual','bank8'],preserve=['R1.identity','R1.units','R3.year','R4.july','R4.august'],review=['Explain new support and duplicate with no new month coverage.','Only entity evidence remains; retain earlier bank evidence.']),dict(id='documentary_final',trigger='Formation and operating agreement saved.',active=allroles+['duplicate'],inactive=['bank_partial'],new=['formation','governing'],revision=6,runState='succeeded',result='6',category='final',requiredReuse=['annual','bank8'],review=['Ground final documentary completeness in all five requests.','Do not imply acceptance, authenticity, approval or readiness.'])]
make('DEV-HISTORY','D02','Previously saved current and historical-period evidence, unlinked but reusable; inactive superseded copy excluded.',history)
# Budget is a deterministic test ledger, not permission to spend or a live budget.
base=['roll','annual','current','bank7','bank8','bank9','formation','governing'];unknownlease={'R2.leases':'unknown','R2.compare':'unknown','R3.compare':'unknown'}
observations=['roll-proof','annual-proof','current-proof','bank-proof','entity-proof','lease-identification']
budget=[dict(id='identified_before_limit',trigger='All files saved; independent short documents assessed; lease identified but execution pages unchecked.',active=allroles,new=allroles,revision=1,runState='running',result=None,states=unknownlease,category='progress',observations=observations,budgetLimit=1000,spent=600,reserved=400,owner='operator',review=['Identification alone does not prove tenant execution.','Preserve completed independent criteria and describe unchecked lease scope.']),dict(id='budget_exhausted',trigger='Trusted reading reservation exhausts remaining limit before execution evidence is observed.',active=allroles,revision=1,runState='partial',result='1',states=unknownlease,category='interruption',observations=observations,budgetLimit=1000,spent=1000,reserved=0,owner='operator',preserve=['R1.identity','R1.units','R3.year','R3.current','R4.july','R4.august','R4.september','R5.formation','R5.governing','R5.consistency'],notice='Reading budget reached. Retain observations; no borrower upload is needed for already saved lease.',review=['Name unchecked lease evidence and operator-owned continuation.','Do not invent absence, completion or ask borrower to upload existing readable files.']),dict(id='resumed_with_observations',trigger='Operator explicitly grants additional reading budget; same immutable evidence revision resumes.',active=allroles,revision=1,runState='running',result='1',states=unknownlease,category='resumption',observations=observations,budgetLimit=2000,spent=1000,reserved=400,owner='operator',requireReuse=True,review=['Reuse persisted observations and preserve progress without restarting investigation.','Any additional reading order/mode is acceptable if justified.']),dict(id='deep_evidence_final',trigger='Qualifying late lease evidence inspected; same evidence revision, new immutable result revision.',active=allroles,revision=1,runState='succeeded',result='2',category='final',observations=observations+['lease-execution-proof'],budgetLimit=2000,spent=1400,reserved=0,requireReuse=True,review=['Support tenant execution and rent comparison with actual late pages.','Report all five requests documented without lender/approval claims.'])]
make('DEV-BUDGET','D06','Scored interrupt/resume ledger; cumulative costs and retained observations; no fixed tool order.',budget)
# D07 stale work finishes during a clear-copy upload. Obscured original remains active until save/supersession.
o,m,s=case('D07');badroles=['roll','obscured','annual','current','bank7','bank8','bank9','formation','governing']
scanunknown={'R2.leases':'unknown','R2.compare':'unknown','R3.compare':'unknown'}
race=[dict(id='unclear_copy',trigger='Original assessment completed on obscured lease version.',active=badroles,revision=2,runState='partial',result='2',states=scanunknown,category='clarification',gold=2,topics=['clearer execution page'],owner='borrower',review=['Request a clearer last-tenant execution page; do not call it a missing lease.']),dict(id='upload_in_flight',trigger='Clear-copy upload begins; no new bytes durably saved yet. Inventory revision changes.',active=badroles,pending=['leases'],revision=3,runState='running',result=None,states=scanunknown,category='arrival',gold=2,owner='operator',review=['Acknowledge in-flight upload without claiming it saved or inspected.','Historical revision-2 findings may be described with scope; no current result yet.']),dict(id='clear_copy_saved',trigger='Upload durably saves and supersedes obscured copy; old worker is still finishing.',active=allroles,inactive=['obscured'],new=['leases'],revision=4,runState='running',result=None,states=scanunknown,category='progress',owner='operator',review=['Saved does not mean assessed. Keep prior independent findings; lease remains unchecked.']),dict(id='stale_result_rejected',trigger='Revision-2 worker attempts publication after revision-4 save; trusted commit rejects stale result.',active=allroles,inactive=['obscured'],revision=4,runState='running',result=None,states=scanunknown,category='correction',owner='operator',review=['Never expose revision-2 completion as current. Do not discard the clear copy or restore superseded links.']),dict(id='current_final',trigger='New worker inspects clear scan and commits revision-4 result.',active=allroles,inactive=['obscured'],revision=4,runState='succeeded',result='4',category='final',review=['Explain resolved unreadability and preserve independent findings.','Citations use the current readable version, never the superseded obscured page.'])]
# D07 cp2 oracle leaves leases missing; override independent entity and bank criteria known met in all race stages.
for st in race:
 if st.get('gold')==2:
  st.setdefault('states',{}).update({k:'met' for k in ['R5.formation','R5.governing','R5.consistency','R4.july','R4.august','R4.september']})
make('DEV-UPLOAD-RACE','D07','In-flight upload and stale-publication fence with explicit evidence revisions.',race)
# Conversation-only boundaries reuse D03 exact corpus but add all intermediate utterance review.
dialog=[]
for bid,cat,gold,active,rev,msg,topics,review in [
 ('arrived','arrival',1,['roll','leases','annual','current'],1,None,[],['Explain which files arrived and partial support; do not claim amendment inspected.']),
 ('focused_question','clarification',1,['roll','leases','annual','current'],1,None,['rent change effective date','applicable amendment'],['Ask a focused question about the unexplained rent change; cite both sides without presuming either wrong.']),
 ('incomplete_answer','response',2,['roll','leases','annual','current','bank7','bank8','bank9','formation','governing'],2,'I think the rent changed; I do not recall when.',[],['Treat vague reply as insufficient evidence; retain completed bank/entity findings.','One focused follow-up or request for applicable amendment is useful; do not restart all questions.']),
 ('amendment_arrival','arrival',2,allroles+['amend0'],3,'Here is the amendment.',[],['Acknowledge saved amendment without claiming its effective-date reconciliation before inspection.']),
 ('correction_explained','correction',3,allroles+['amend0'],3,None,[],['Explain effective-date reconciliation and what changed, preserving unaffected findings.']),
 ('grounded_final','final',3,allroles+['amend0'],3,None,[],['Summarize qualifying evidence for all five requests and any remaining gaps honestly.','Do not equate documentary completeness with readiness or approval.'])]:
 dialog.append(dict(id=bid,trigger='External conversation boundary: '+cat,category=cat,gold=gold,active=active,revision=rev,runState='running' if bid=='amendment_arrival' else 'succeeded',result=None if bid=='amendment_arrival' else str(rev),message=msg,topics=topics,review=review))
for st in dialog:
 if st['id']=='amendment_arrival':st['states']={'R2.chain':'unknown','R2.compare':'unknown','R3.compare':'unknown'}
